package com.lexiscan.document; import com.lexiscan.analysis.*; import com.lexiscan.user.User; import jakarta.validation.*; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.util.*;
@RestController @RequestMapping("/api/documents") public class DocumentController {final DocumentService ds;final DocumentRepository repo;final AnalysisService as; public DocumentController(DocumentService d,DocumentRepository r,AnalysisService a){ds=d;repo=r;as=a;} record View(UUID id,String fileName,DocumentStatus status,String riskLevel){} @PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE) View upload(@AuthenticationPrincipal User u,@RequestPart("file") MultipartFile f)throws Exception{var d=ds.upload(u,f);return view(d);}@GetMapping Page<View> list(@AuthenticationPrincipal User u,@PageableDefault(size=20,sort="uploadedAt",direction=Sort.Direction.DESC) Pageable p){return repo.findByUserId(u.getId(),p).map(this::view);}@GetMapping("/{id}") View get(@PathVariable UUID id,@AuthenticationPrincipal User u){return view(ds.mine(id,u));}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void delete(@PathVariable UUID id,@AuthenticationPrincipal User u){ds.delete(id,u);}@PostMapping("/{id}/analyze") @ResponseStatus(HttpStatus.ACCEPTED) void analyze(@PathVariable UUID id,@AuthenticationPrincipal User u){as.trigger(id,u);} View view(Document d){return new View(d.getId(),d.getFileName(),d.getStatus(),d.getStatus()==DocumentStatus.ANALYZED?as.result(d).getOverallRiskLevel():null);} }
